for entry in split_by_nl:
    f_str = entry.split("(")[-1]
    f_str = f_str.split(")")[0]
    idd = int(f_str)
    if idd not in no_id and idd not in skip_ids:
        no_id.append(idd)
        unfilt_names.append(entry)
print(f'AFTER ID CHECK: {len(no_id)}')

unaccounted = []
name_checklist = []
for entry in unfilt_names:
    if len(entry) < 5:
        continue
       
    no_id_name = "(".join(entry.split('(')[0:-1])
    
    if no_id_name not in skip_ids and no_id_name not in name_checklist:
        name_checklist.append(no_id_name)
        unaccounted.append(entry)
print(f'AFTER NAME CHECK: {len(unaccounted)}')
print('-----------------------------------------------------')
print('-----------------------------------------------------')
print('-----------------------------------------------------')
unaccounted.sort()
print("\n".join(unaccounted))
